/// <summary>
/// The data contract for a <c>METSalesOrderCancelledBusinessEvent</c>.
/// </summary>
[DataContract]
public final class METSalesOrderCancelledBusinessEventContract extends BusinessEventsContract
{
    private DataAreaId dataAreaId;

}

Method.Source:
    /// <summary>
    /// Creates an instance of <C>METSalesOrderCancelledBusinessEventContract</C>
    /// </summary>
    /// <param name = "_dataAreaId">company</param>
    /// <returns>new instance of <C>METSalesOrderCancelledBusinessEventContract</C></returns>
    public static METSalesOrderCancelledBusinessEventContract newFromDataAreaId(DataAreaId _dataAreaId)
    {
        METSalesOrderCancelledBusinessEventContract contract = new METSalesOrderCancelledBusinessEventContract();
                     
        contract.initialize(_dataAreaId);

        return contract;
    }

/// <summary>
/// initialize the data contract
/// </summary>
/// <param name = "_dataAreaId">dataAreaId</param>
private void initialize(DataAreaId _dataAreaId)
{
    dataAreaId = _dataAreaId;
}

    /// <summary>
    /// Gets/sets the company ID
    /// </summary>
    /// <param name = "_dataAreaId">company ID</param>
    /// <returns>returns the company ID</returns>
    [DataMember('LegalEntity'), BusinessEventsDataMember("@SYS315616")]
    public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
    {
        dataAreaId = _dataAreaId;

        return dataAreaId;
    }
